if(!exists('covered_bond_dual_recourse'))library(creditratingsystem)
spa_D<-'2023-01-01';spa_dates<-list('2023-07-01','2024-01-01')
spa_asset<-function(id='a',group='g')list(asset_id=id,asset_class='AUTO_LOAN',invoice_id=NULL,obligor_id=group,default_group_id=group,seller_id='seller',servicer_id='service',currency='EUR',observed_at=spa_D,known_at=spa_D,origination_date='2022-01-01',balance_date=spa_D,principal_balance=100,schedule=list(list(date=spa_dates[[1]],principal_due=40,interest_due=5),list(date=spa_dates[[2]],principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
spa_assignment<-function(id='m',aid='a',start=spa_D,price=100)list(assignment_id=id,pool_id='pool',asset_id=aid,known_at=spa_D,effective_from=start,effective_until=NULL,share=1,purchase_price=price,purchase_priority=1)
spa_fixture<-function(assets=list(spa_asset()),assignments=list(spa_assignment()),revolving=FALSE){
 p<-list(profile_id='p',version='1',known_at=spa_D,currency='EUR',product_kind='ABS',pool_mode=if(revolving)'REVOLVING'else'STATIC',allowed_asset_classes=list('AUTO_LOAN'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=if(revolving)spa_dates[[2]]else NULL)
 pool<-build_credit_asset_pool(assets,assignments,p,'pool',spa_D,spa_D)$value
 contract<-list(contract_id='c',version='1',scenario_ids=list('s'),weights=list(1),dates=spa_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT',default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY',initial_reinvestment_cash=0)
 gp<-ap<-innov<-list();for(g in sort(unique(vapply(assets,function(a)a$default_group_id,''))))for(d in spa_dates){gp[[length(gp)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=paste0('default-',g));innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('default-',g),uniform=.5)}
 for(a in assets)for(d in spa_dates){ap[[length(ap)+1L]]<-list(scenario_id='s',asset_id=a$asset_id,date=d,conditional_prepayment_probability=0,prepayment_channel=paste0('prepay-',a$asset_id),dilution_fraction=0,recovery_fraction=.4,recovery_delay_days=30,recovery_cost=5,servicing_cost=0,interest_multiplier=1,overdue_days=0,disputed=FALSE);innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('prepay-',a$asset_id),uniform=.5)}
 list(asset_pool=pool,scenario_contract=contract,obligor_paths=gp,asset_paths=ap,shared_innovations=innov)
}
spa_run<-function(f)do.call(simulate_asset_pool,f)$value
spa_total<-function(r,key)sum(vapply(r$cashflows,function(c)c[[key]],0.))
spa_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}

scov_fixture<-function(kind='MORTGAGE_COVER',extension=FALSE,default=spa_D){cls<-if(kind=='MORTGAGE_COVER')'RESIDENTIAL_MORTGAGE'else'PUBLIC_SECTOR_CLAIM';a<-spa_asset();a$asset_class<-cls;p<-list(profile_id='cover',version='1',known_at=spa_D,currency='EUR',product_kind=kind,pool_mode='STATIC',allowed_asset_classes=list(cls),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=NULL);cover<-build_credit_asset_pool(list(a),list(spa_assignment()),p,'pool',spa_D,spa_D)$value;f<-spa_fixture();f$asset_pool<-cover;paths<-spa_run(f);bond<-list(bond_id='covered',version='1',currency='EUR',legal_profile_id='caller-law-1',principal=100,original_maturity=spa_dates[[2]],extended_maturity=if(extension)'2024-07-01'else NULL,interest_schedule=setNames(list(),character()),extension_interest_schedule=if(extension)list('2024-07-01'=5)else setNames(list(),character()),extension_rule=if(extension)'ISSUER_DEFAULT_AND_DECLARED_TRIGGER'else'NONE',cover_cash_convention='SEGREGATED_UNTIL_ISSUER_DEFAULT',estate_rule='RESIDUAL_AFTER_COMPLETE_COVER',innovation_hash=paths$innovation_hash);issuer<-list(list(scenario_id='s',issuer_default_date=default,issuer_capacity=setNames(list(100),spa_dates[[2]]),extension_triggered=extension,estate_payment_date=if(extension)'2024-07-01'else spa_dates[[2]],estate_recovery_fraction=.5,estate_capacity=1000));list(args=list(cover_pool=cover,cover_pool_paths=paths,bond_contract=bond,issuer_paths=issuer),pool_fixture=f)}
scov_run<-function(f)do.call(covered_bond_dual_recourse,f)$value
f<-scov_fixture()$args;r<-scov_run(f);e<-r$ending_states[[1]];stopifnot(e$cover_payment==100,e$estate_payment==0,e$ultimate_shortfall==0,e$unused_cover_cash==8);f$issuer_paths[[1]]['issuer_default_date']<-list(NULL);e<-scov_run(f)$ending_states[[1]];stopifnot(e$issuer_payment==100,e$cover_payment==0,e$estate_payment==0,e$unused_cover_cash==108)
z<-scov_fixture();z$pool_fixture$obligor_paths[[1]]$conditional_pd<-1;f<-z$args;f$cover_pool_paths<-spa_run(z$pool_fixture);r<-scov_run(f);e<-r$ending_states[[1]];stopifnot(e$cover_payment==35,e$estate_payment==32.5,e$ultimate_shortfall==32.5,sum(vapply(r$cashflows,function(x)x$issuer_payment+x$cover_payment+x$estate_payment,0.))==67.5,all(vapply(r$cashflows,function(x)x$cover_conservation_residual==0,TRUE)));f$issuer_paths[[1]]$estate_capacity<-10;stopifnot(scov_run(f)$ending_states[[1]]$ultimate_shortfall==55)
f<-scov_fixture('PUBLIC_SECTOR_COVER',TRUE)$args;r<-scov_run(f);e<-r$ending_states[[1]];stopifnot(e$extension_activated,e$contractual_claim==105,e$cover_payment==105,e$original_date_principal_deferral_or_shortfall==100,e$effective_maturity_principal_shortfall==0,e$unused_cover_cash==3,e$ultimate_shortfall==0,all(vapply(Filter(function(x)x$date<'2024-07-01',r$cashflows),function(x)x$principal_paid==0,TRUE)))
f<-scov_fixture(extension=TRUE)$args;f$issuer_paths[[1]]$extension_triggered<-FALSE;e<-scov_run(f)$ending_states[[1]];stopifnot(e$contractual_claim==100,e$effective_maturity==spa_dates[[2]],e$cover_payment==100)
f<-scov_fixture(default=NULL)$args;f$issuer_paths[[1]]$issuer_capacity<-list('2024-07-01'=120);f$issuer_paths[[1]]$estate_payment_date<-'2024-07-01';e<-scov_run(f)$ending_states[[1]];stopifnot(e$effective_maturity_principal_shortfall==100,e$ultimate_shortfall==0,e$issuer_payment==100)
f<-scov_fixture(extension=TRUE)$args;f$issuer_paths[[1]]['issuer_default_date']<-list(NULL);spa_error('STRUCTURED_EXTENSION',scov_run(f));f<-scov_fixture()$args;f$issuer_paths[[1]]$estate_payment_date<-spa_dates[[1]];spa_error('STRUCTURED_CALENDAR',scov_run(f));f<-scov_fixture()$args;f$bond_contract$innovation_hash<-'wrong';spa_error('STRUCTURED_SHARED_PATHS',scov_run(f));z<-scov_fixture();z$pool_fixture$obligor_paths[[1]]$conditional_pd<-1;z$pool_fixture$asset_paths[[1]]$recovery_delay_days<-1000;f<-z$args;f$cover_pool_paths<-spa_run(z$pool_fixture);spa_error('STRUCTURED_UNRESOLVED',scov_run(f))
cat('Native covered bond capped recourse, issuer joint stress and maturity extension PASS\n')

f<-scov_fixture()$args;f$context<-list(horizon=1,time_unit='years');spa_error('TARGET_MISMATCH',scov_run(f));f$context<-list(horizon=365,time_unit='days');stopifnot(scov_run(f)$horizon_end==spa_dates[[2]])
